{
  "cases": [
    {
      "id": "C1",
      "instrument_review": "MESA distinguishes missing information about repeated testing from evidence of stability. Neither repeated testing nor stable scores is established here.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "The passage leaves repeated testing unknown."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish variation across repeated runs."
        }
      ]
    },
    {
      "id": "C2",
      "instrument_review": "Under MESA, the explicit statement rules out repeated testing for this evaluation. It leaves score stability unresolved.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "The developers explicitly state that no repetition occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "Without repeated results, stability is unknown; a single run does not demonstrate instability either."
        }
      ]
    },
    {
      "id": "C3",
      "instrument_review": "MESA asks separately whether repetition occurred and whether results support consistency. Both are supported within the stated conditions and definition of stability.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations under the same conditions are explicitly reported."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The observed range meets the report's stated stability criterion."
        }
      ]
    },
    {
      "id": "C4",
      "instrument_review": "MESA counts repeated testing as conducted even when results are unfavourable. The observed variation conflicts with the stated stability criterion.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The passage explicitly reports repeated testing under unchanged conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The reported range exceeds the stated stability limit."
        }
      ]
    },
    {
      "id": "C5",
      "instrument_review": "MESA separates instructions that help others run an evaluation from evidence about repeated results. The installation information resolves neither repetition nor stability.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not establish that repeated evaluations occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "No repeated score findings are supplied to assess stability."
        }
      ]
    },
    {
      "id": "C6",
      "instrument_review": "MESA keeps interpretation within the tested tasks and intended use. The results support the grid-puzzle comparison but do not establish general intelligence across domains.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more of the evaluated puzzles under the stated scoring conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The results provide no evidence establishing a comparison across domains."
        }
      ]
    },
    {
      "id": "C7",
      "instrument_review": "MESA distinguishes intended use from evidence supporting that use. The grid-puzzle comparison is supported, but selecting for general intelligence exceeds the supplied evidence.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A performed better on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broad intended use does not supply evidence of greater general intelligence."
        }
      ]
    },
    {
      "id": "C8",
      "instrument_review": "MESA asks for evidence connecting test scores to the intended real task. The later trial supports decision correctness in the studied workshop; initial scores alone and unmeasured safety outcomes do not support the broader claims.",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "Those scores alone do not establish improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%. The reported uncertainty interval for the difference was 12 to 28 percentage points.",
          "reason": "The randomly allocated trial and reported interval support better correctness with A in the studied workshop and conditions."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "The trial supplies no measured safety outcome establishing improvement."
        }
      ]
    }
  ],
  "closing_note": "No instructions were unclear. Each case was assessed independently using only its supplied passage."
}
